:root {
  --ink: #183443;
  --muted: #647984;
  --paper: #fffdf7;
  --line: #cbd8d6;
  --teal: #147b78;
  --teal-soft: #e0f1ed;
  --amber: #f2b84b;
  --amber-soft: #fff0cc;
}

* {
  box-sizing: border-box;
}

.reader-card {
  width: 480px;
  overflow: hidden;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 16px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--teal-soft);
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0;
  color: var(--teal);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.request-state {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--amber-soft);
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

.booking-main {
  display: grid;
  grid-template-columns: 1fr 154px;
  gap: 16px;
  padding: 16px;
}

.booking-copy {
  min-width: 0;
}

.booking-title {
  margin: 0 0 3px;
  font-size: 21px;
  line-height: 1.15;
}

.booking-note {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.35;
}

.detail-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 16px 0 0;
  padding: 0;
  list-style: none;
}

.detail-list li {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 12px;
  line-height: 1.25;
}

.detail-label {
  color: var(--muted);
  font-size: 11px;
}

.slot-panel {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  gap: 7px;
  padding: 12px;
  background: var(--ink);
  border-radius: 12px;
  color: var(--paper);
}

.slot-label {
  color: var(--amber);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.time-value {
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.confirm {
  width: 100%;
  margin-top: 3px;
  padding: 7px 8px;
  border: 0;
  border-radius: 7px;
  background: var(--amber);
  color: var(--ink);
  font-size: 12px;
  font-weight: 700;
}

.card-footer {
  display: flex;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}

.footer-code {
  color: var(--teal);
  font-weight: 700;
  letter-spacing: 0.04em;
}

.footer-note {
  font-style: italic;
}
